sp_widget.client_script:
api.controller = function($location, $scope, $timeout) {
    /* widget controller */
    var c = this;
    c.showDetailModal = false;
    c.showDisputeModal = false;
    c.currentStatement = null;
    c.disputeData = {
        reason: '',
        comments: ''
    };


    c.viewStatement = function(statementId) {

			window.location = '?id=incentive_statement_view&statement_id=' + statementId;
        /*c.server.get({
            action: 'get_statement_detail',
            statement_id: statementId
        }).then(function(response) {
            c.currentStatement = response.data.statement;
            c.showDetailModal = true;
        });*/
    };

    c.closeDetailModal = function() {
        c.showDetailModal = false;
        c.currentStatement = null;
    };

    c.openDisputeModal = function(statement) {
        c.currentStatement = statement;
        c.disputeData = {
            reason: '',
            comments: ''
        };
        c.showDisputeModal = true;
    };

    c.closeDisputeModal = function() {
        c.showDisputeModal = false;
        c.disputeData = {
            reason: '',
            comments: ''
        };
    };

    c.submitDispute = function() {
        if (!c.disputeData.reason || !c.disputeData.comments) {
            alert('Please fill in all fields');
            return;
        }

        c.server.update({
            action: 'submit_dispute',
            statement_id: c.currentStatement.id,
            reason: c.disputeData.reason,
            comments: c.disputeData.comments
        }).then(function(response) {
            if (response.data.success) {
                c.closeDisputeModal();
                c.loadStatements();
                alert('Dispute submitted successfully');
            }
        });
    };

    c.downloadPDF = function() {

				var url='/api/x_incent/statement/' + c.currentStatement.id + '/pdf';
				$location.url(url);
    };

    c.generateStatements = function() {

			var url ='?id=incentnow_generate_statements';
			$location.url(url);
    };

		// Pagination
		c.currentPage = 1;
		c.pageSize = 10; // rows per page

		c.getPaginatedStatements = function() {
				if (!c.data.statements) return [];

				var start = (c.currentPage - 1) * c.pageSize;
				var end = start + c.pageSize;

				return c.data.statements.slice(start, end);
		};

		c.totalPages = function() {
				if (!c.data.statements || c.data.statements.length === 0) return 0;
				return Math.ceil(c.data.statements.length / c.pageSize);
		};

		c.nextPage = function() {
				if (c.currentPage < c.totalPages()) {
						c.currentPage++;
				}
		};

		c.prevPage = function() {
				if (c.currentPage > 1) {
						c.currentPage--;
				}
		};

	 /* Formatting currency without $scope */
    c.currencySymbol = c.data.currencySymbol;
		c.currencyPosition = c.data.currencyPosition || 'before';

		this.formatCurrency = function(num) {

				num = Number(num) || 0;
				var formatted = num.toLocaleString();

				if (c.currencyPosition == "after") {
						return formatted + c.currencySymbol;
				}

				return c.currencySymbol + formatted;
		};

		// Approval Flow Pagination
		c.approvalCurrentPage = 1;
		c.approvalPageSize = 5;

		c.getPaginatedApprovalFlow = function () {

				if (!c.approvalFlow)
						return [];

				var start = (c.approvalCurrentPage - 1) * c.approvalPageSize;
				var end = start + c.approvalPageSize;

				return c.approvalFlow.slice(start, end);
		};

		c.approvalTotalPages = function () {

				if (!c.approvalFlow || c.approvalFlow.length === 0)
						return 1;

				return Math.ceil(c.approvalFlow.length / c.approvalPageSize);
		};

		c.nextApprovalPage = function () {

				if (c.approvalCurrentPage < c.approvalTotalPages()) {
						c.approvalCurrentPage++;
				}
		};

		c.prevApprovalPage = function () {

				if (c.approvalCurrentPage > 1) {
						c.approvalCurrentPage--;
				}
		};

		//approval flow

		c.showApprovalFlow = false;
		c.approvalFlow = [];

		c.openApprovalFlow = function(statementId) {

				c.server.get({
						action: "getApprovalFlow",
						statementId: statementId
				}).then(function(response) {

						c.approvalFlow = response.data.approvalFlow;
						c.showApprovalFlow = true;
				});
		};

		$scope.$on('showStatementApprovalFlow', function(event, data) {

				c.server.get({
						action: 'getApprovalFlow',
						statementId: data.statementId
				}).then(function(response){

						c.approvalFlow = response.data.approvalFlow;
						c.approvalCurrentPage = 1; 
						c.showApprovalFlow = true;

						$timeout(function () {

						var el = document.getElementById("approvalFlowSection");

						if (el) {
								el.scrollIntoView({
										behavior: "smooth",
										block: "start"
								});
						}

				}, 100);

				});

		});

};

sp_widget.css:
