}
/* ============================================================
   INCENTIVE STATEMENTS
   MOBILE RESPONSIVE OVERRIDES
   Existing HTML / Angular / JS untouched
   ============================================================ */


/* ------------------------------------------------------------
   TABLET
   ------------------------------------------------------------ */
@media (max-width: 991px) {

  .incentive-statements {
    width: 100%;
    max-width: 100%;
    overflow-x: hidden;
  }

  /* Header */
  .incentive-statements .statement-headers {
    flex-wrap: wrap;
    gap: 12px;
  }

  .incentive-statements .actions {
    flex-wrap: wrap;
  }

  /* Stats */
  .incentive-statements .stats-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
  }

  .incentive-statements .stat-box {
    min-width: 0;
  }

  /* Cards */
  .incentive-statements .card-box {
    margin: 8px;
  }

  /* Tables */
  .incentive-statements .panel-body {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .incentive-statements .table {
    min-width: 700px;
  }

  /* Bootstrap columns */
  .incentive-statements .col-md-3 {
    width: 50%;
  }
}


/* ------------------------------------------------------------
   MOBILE
   ------------------------------------------------------------ */
@media (max-width: 767px) {

  .incentive-statements {
    width: 100%;
    max-width: 100%;
    padding: 0 8px;
    box-sizing: border-box;
    overflow-x: hidden;
  }


  /* ==========================================================
     PAGE / HEADING
     ========================================================== */

  .incentive-statements .h2 {
    font-size: 2.1rem;
    line-height: 1.2;
  }

  .incentive-statements .heading {
    margin-left: 0;
    font-size: 1.25rem;
  }

  .incentive-statements .statement {
    margin-left: 0;
    font-size: 12px;
  }

  .incentive-statements .btn-generate {
    width: 100%;
    justify-content: center;
    min-height: 40px;
    padding: 8px 14px;
    font-size: 12px;
  }


  /* ==========================================================
     STAT CARDS
     ========================================================== */

  .incentive-statements .stats-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    margin-bottom: 20px;
  }

  .incentive-statements .stat-box {
    width: 100%;
    min-width: 0;
    padding: 14px;
    border-radius: 10px;
  }

  .incentive-statements .box {
    font-size: 11px;
    line-height: 1.35;
    margin-bottom: 8px;
  }

  .incentive-statements .set {
    font-size: 2.1rem !important;
    line-height: 1.1;
    margin-bottom: 6px;
    overflow-wrap: anywhere;
  }

  .incentive-statements .stat-box h3 {
    font-size: 2.2rem;
    line-height: 1.1;
  }

  .incentive-statements .stat-box span {
    font-size: 10px;
    line-height: 1.4;
  }


  /* ==========================================================
     FILTER / STATEMENT HEADER
     ========================================================== */

  .incentive-statements .statement-header {
    padding: 14px;
    margin-bottom: 14px;
    border-radius: 9px;
  }

  .incentive-statements .statement-headers {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    padding: 10px 0;
  }

  .incentive-statements .left-info h2 {
    font-size: 17px;
    line-height: 1.3;
  }

  .incentive-statements .status-chip {
    font-size: 10px;
    padding: 3px 8px;
  }

  .incentive-statements .actions {
    width: 100%;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }


  /* ==========================================================
     BUTTONS
     ========================================================== */

  .incentive-statements .btn-xs {
    min-height: 36px;
    height: 36px;
    padding: 0 10px;
    font-size: 11px;
  }

  .incentive-statements .btn-light,
  .incentive-statements .btn-dark {
    min-height: 38px;
    font-size: 12px;
  }


  /* ==========================================================
     PANEL
     ========================================================== */

  .incentive-statements .panel {
    width: 100%;
    max-width: 100%;
    border-radius: 10px;
  }

  .incentive-statements .panel-body {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
    padding: 12px;
    -webkit-overflow-scrolling: touch;
  }

  .incentive-statements .panel-head {
    margin: 14px 0 8px 0 !important;
    padding: 0;
  }

  .incentive-statements .panel-tile.ng-binding {
    margin: 14px 0 8px 0 !important;
    font-size: 1.3rem !important;
  }


  /* ==========================================================
     TABLE
     ========================================================== */

  .incentive-statements .table {
    min-width: 700px;
    margin-bottom: 0;
  }

  .incentive-statements .table th,
  .incentive-statements .table td {
    font-size: 11px;
    padding: 8px 9px;
    vertical-align: middle;
    white-space: nowrap;
  }

  .incentive-statements .table th {
    font-size: 10px;
  }

  .incentive-statements .table code {
    font-size: 10px;
  }

  .incentive-statements .badge-success {
    font-size: 10px;
    padding: 3px 7px;
  }


  /* ==========================================================
     CARD BOX
     ========================================================== */

  .incentive-statements .card-box {
    width: 100%;
    max-width: 100%;
    margin: 8px 0;
    padding: 14px;
    border-radius: 9px;
    box-sizing: border-box;
  }

  .incentive-statements .box-header {
    font-size: 12px;
  }

  .incentive-statements .box-amount {
    font-size: 2rem;
    margin-top: 1.5rem;
  }

  .incentive-statements .box-sub {
    font-size: 11px;
  }


  /* ==========================================================
     PERIOD COMPARISON
     ========================================================== */

  .incentive-statements .period-compare-row .row-item {
    gap: 8px;
    margin-bottom: 7px;
  }

  .incentive-statements .label-txt,
  .incentive-statements .value-txt {
    font-size: 11px;
  }


  /* ==========================================================
     PROGRESS
     ========================================================== */

  .incentive-statements .progress {
    height: 5px;
  }


  /* ==========================================================
     DESCRIPTION
     ========================================================== */

  .incentive-statements .desc {
    font-size: 11px;
    line-height: 1.5;
  }


  /* ==========================================================
     MODAL
     ========================================================== */

  .incentive-statements .modal {
    padding-left: 8px;
    padding-right: 8px;
  }

  .incentive-statements .modal-dialog {
    width: auto;
    max-width: 100%;
    margin: 10px auto;
  }

  .incentive-statements .modal-content {
    border-radius: 10px;
  }


  /* ==========================================================
     BOOTSTRAP COLUMNS
     ========================================================== */

  .incentive-statements .col-sm-3 {
    width: 50%;
    padding-left: 8px;
    padding-right: 8px;
  }

  .incentive-statements .col-md-3 {
    width: 50%;
  }
}


/* ------------------------------------------------------------
   SMALL PHONES
   ------------------------------------------------------------ */
@media (max-width: 480px) {

  .incentive-statements {
    padding: 0 6px;
  }

  .incentive-statements .h2 {
    font-size: 1.9rem;
  }

  .incentive-statements .heading {
    font-size: 1.15rem;
  }

  .incentive-statements .statement {
    font-size: 11px;
  }


  /* Stats */
  .incentive-statements .stats-row {
    gap: 8px;
  }

  .incentive-statements .stat-box {
    padding: 11px;
  }

  .incentive-statements .box {
    font-size: 10px;
  }

  .incentive-statements .set {
    font-size: 1.8rem !important;
  }

  .incentive-statements .stat-box h3 {
    font-size: 1.9rem;
  }

  .incentive-statements .stat-box span {
    font-size: 9px;
  }


  /* Buttons */
  .incentive-statements .actions {
    gap: 5px;
  }

  .incentive-statements .btn-xs {
    font-size: 10px;
    padding: 0 8px;
  }


  /* Table */
  .incentive-statements .table {
    min-width: 620px;
  }

  .incentive-statements .table th,
  .incentive-statements .table td {
    font-size: 10px;
    padding: 7px 8px;
  }


  /* Card */
  .incentive-statements .card-box {
    padding: 12px;
  }

  .incentive-statements .box-amount {
    font-size: 1.8rem;
  }
}


/* ------------------------------------------------------------
   EXTRA SMALL PHONES
   ------------------------------------------------------------ */
@media (max-width: 360px) {

  .incentive-statements {
    padding: 0 5px;
  }

  .incentive-statements .stats-row {
    grid-template-columns: 1fr;
  }

  .incentive-statements .set {
    font-size: 1.9rem !important;
  }

  .incentive-statements .stat-box h3 {
    font-size: 2rem;
  }

  .incentive-statements .table {
    min-width: 580px;
  }

  .incentive-statements .card-box {
    padding: 10px;
  }

  .incentive-statements .box-amount {
    font-size: 1.7rem;
  }
}


/* ------------------------------------------------------------
   MOBILE SAFETY
   ------------------------------------------------------------ */
@media (max-width: 767px) {

  .incentive-statements,
  .incentive-statements .panel,
  .incentive-statements .panel-body,
  .incentive-statements .card-box,
  .incentive-statements .statement-header {
    max-width: 100%;
    box-sizing: border-box;
  }

  /*
     Prevent the complete ServiceNow page from becoming
     horizontally scrollable.
  */
  .incentive-statements {
    overflow-x: hidden;
  }

  /*
     Tables scroll independently when their columns need
     more width than the phone.
  */
  .incentive-statements .panel-body {
    overscroll-behavior-x: contain;
  }
}

sp_widget.script:
(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
    // Check if user is admin
		data.currencySymbol = gs.getProperty('x_ctans_incentnow.currency_symbol', '$');
		data.currencyPosition = gs.getProperty('x_ctans_incentnow.currency_position', 'before');
		data.tableWidget=$sp.getWidget('incentnow-table-widget',{ table: 'x_ctans_incentnow_incentive_statement',view:'portal_view',viewperiod:'false'});
    data.isAdmin =
    gs.hasRole('x_ctans_incentnow.admin') ||
    gs.hasRole('x_ctans_incentnow.manager') ||
		gs.hasRole('x_ctans_incentnow.business_group_executive') ||
		gs.hasRole('x_ctans_incentnow.business_group_admin') ||
		gs.hasRole('x_ctans_incentnow.org_executive');
		//data.isAdmin = gs.hasRole('snc_internal'); 

		data.isIncentBusinessGroupAdmin =
    gs.hasRole('x_ctans_incentnow.admin') || gs.hasRole('x_ctans_incentnow.business_group_admin') || gs.hasRole('x_ctans_incentnow.territory_admin');
    // Get statements
		data.statements = [];
		var stmtGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');

		//================ Statement Dashboard Statistics ================
		data.statementStats = {
				published: 0,
				generated: 0,
				pending: 0,
				totalCommission: 0
		};

		var statsGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');

		// Restrict for non-admin
		if (!data.isAdmin) {
				var profileGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
				profileGR.addQuery('user', gs.getUserID());
				profileGR.setLimit(1);
				profileGR.query();

				if (profileGR.next()) {
						statsGR.addQuery('user', profileGR.getUniqueValue());
				}
		}

		statsGR.query();
		while (statsGR.next()) {
				var status = statsGR.getValue('status');
				if (status == 'statement_published') {
						data.statementStats.published++;
						data.statementStats.totalCommission += parseFloat(statsGR.getValue('total_commission') || 0);
				}
				else if (status == 'statement_generated') {
						data.statementStats.generated++;
				}
				else if (status == 'pending_approval') {
						data.statementStats.pending++;
				}
		}

  // Status Filter
	stmtGR.addQuery('status', 'statement_generated');
 if (!data.isAdmin) {

				var profileGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
				profileGR.addQuery('user', gs.getUserID()); // adjust field name if needed
				profileGR.setLimit(1);
				profileGR.query();

				if (profileGR.next()) {
						stmtGR.addQuery('user', profileGR.getUniqueValue());
				}
		}

		stmtGR.orderByDesc('sys_created_on');
		stmtGR.query();

		//gs.addInfoMessage(stmtGR.getEncodedQuery());

		while (stmtGR.next()) {
				var totalComm = parseFloat(stmtGR.getValue('total_commission') || 0);
				var userEmail = '';
					if (stmtGR.getValue('user')) {
							var userGR = new GlideRecordSecure('sys_user');
							if (userGR.get(stmtGR.getValue('user'))) {
									userEmail = userGR.getValue('email') || '';
							}
					}

				data.statements.push({
						id: stmtGR.getUniqueValue(),
						userName: stmtGR.getDisplayValue('user'), // Shows the 'name' from the User table automatically
						//userEmail: stmtGR.user ? stmtGR.user.email.toString() : '',
						userEmail: userEmail,
						periodName: stmtGR.getDisplayValue('fiscal_period'),
						generatedDate: stmtGR.getDisplayValue('sys_updated_on'),
						totalCommission: totalComm,
						totalCommissionDisplay: totalComm.toFixed(2),
						status: stmtGR.getDisplayValue('status')

				});
		}

	// commission rule breakdown --------------------------
		data.ruleDetails = {};
	// Create GlideRecord for incentive statements
	var recGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');


  // Status Filter
	recGR.addQuery('status', 'statement_generated');	

 if (!data.isAdmin) {
			// Initial load for non-admins
			recGR.addQuery('user', gs.getUserID());
	}

	// Sort by generated date (latest first)
	recGR.orderByDesc('u_generated_date');
	recGR.query();

	// Pick the first record if available
	if (recGR.next()) {
			var rawJson = recGR.getValue('payout_results'); // JSON field

			if (rawJson) {
					try {
							data.ruleDetails = JSON.parse(rawJson);
					} catch (e) {
							data.ruleDetails = { error: "Invalid JSON format" };
					}
			}
	}

    // Handle get statement detail
    if (input && input.action === 'get_statement_detail') {
        var detailGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');
        if (detailGR.get(input.statement_id)) {
            // Get user info
            var userName = '';
            var userEmail = '';
            if (detailGR.user.toString()) {
                var u = new GlideRecordSecure('x_ctans_incentnow_user_profile');
                if (u.get(detailGR.user.toString())) {
                    userName = u.getValue('name');
                    userEmail = u.getValue('email');
                }
            }

            // Get period name
            var periodName = '';
            if (detailGR.fiscal_period.toString()) {
                var p = new GlideRecordSecure('x_ctans_incentnow_fiscal_period');
                if (p.get(detailGR.fiscal_period.toString())) {
                    periodName = p.getValue('u_name');
                }
            }

            // Get line items
            var lineItems = [];
            var lineGR = new GlideRecordSecure('x_1776231_incent_0_u_statement_line_item');
            lineGR.addQuery('u_statement', input.statement_id);
            lineGR.orderBy('u_order');
            lineGR.query();
            while (lineGR.next()) {
                lineItems.push({
                    ruleName: lineGR.getValue('u_payout_rule_name'),
                    calculation: lineGR.getValue('u_calculation_detail'),
                    amount: parseFloat(lineGR.getValue('u_amount') || 0),
                    amountDisplay: (parseFloat(lineGR.getValue('u_amount') || 0)).toFixed(2)
                });
            }

            data.statement = {
                id: detailGR.getUniqueValue(),
                userName: userName,
                userEmail: userEmail,
                periodName: periodName,
                totalCommission: parseFloat(detailGR.getValue('u_total_commission') || 0),
                totalCommissionDisplay: (parseFloat(detailGR.getValue('u_total_commission') || 0)).toFixed(2),
                status: detailGR.getValue('u_status'),
                lineItems: lineItems,
                disputeReason: detailGR.getValue('u_dispute_reason'),
                disputeComments: detailGR.getValue('u_dispute_comments'),
                disputeDate: detailGR.getValue('u_dispute_date')
            };
        }
    }

    // Handle submit dispute
    if (input && input.action === 'submit_dispute') {
        var disputeGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');
        if (disputeGR.get(input.statement_id)) {
            disputeGR.setValue('u_status', 'disputed');
            disputeGR.setValue('u_dispute_reason', input.reason);
            disputeGR.setValue('u_dispute_comments', input.comments);
            disputeGR.setValue('u_dispute_date', new GlideDateTime());
            disputeGR.update();
            data.success = true;
        }
    }

    // Handle generate statements
    if (input && input.action === 'generate_statements' && data.isAdmin) {

        var generator = new IncentiveStatementGenerator();

        var planGR = new GlideRecordSecure('x_ctans_incentnow_plan');
        planGR.addQuery('u_status', 'active');
        planGR.setLimit(1);
        planGR.query();

        if (planGR.next()) {

            var result;

            if (input.user) {

                // Generate for single user
                result = generator.generateUserStatement(
                    planGR.getUniqueValue(),
                    input.period,
                    input.user
                );

                data.count = result.success;

            } else {

                // Generate for all users
                result = generator.generateBulkStatements(
                    planGR.getUniqueValue(),
                    input.period
                );

                data.count = result.success;

            }

            data.success = true;

        }

    }

		//approval flow

		if (input && input.action == "getApprovalFlow") {

				data.approvalFlow = [];

				var apprGR = new GlideRecordSecure('sysapproval_approver');
				apprGR.addQuery('document_id', input.statementId);
				apprGR.orderByDesc('sys_created_on');
				apprGR.query();

				while (apprGR.next()) {
						data.approvalFlow.push({
								approver: apprGR.getDisplayValue('approver'),
								state: apprGR.getDisplayValue('state'),
								updated: apprGR.getDisplayValue('sys_updated_on'),
								comments: apprGR.getDisplayValue('comments')
						});
				}
		}

})();
